<?php require_once __DIR__ . '/../app/bootstrap.php'; use App\Middleware\AuthMiddleware; use App\Models\FitnessClass; use App\Security\Csrf; AuthMiddleware::requireRole('admin'); if($_SERVER['REQUEST_METHOD']==='POST' && Csrf::verify($_POST['_csrf']??null)){FitnessClass::create(['title'=>trim($_POST['title']),'description'=>trim($_POST['description']),'instructor_id'=>!empty($_POST['instructor_id'])?(int)$_POST['instructor_id']:null,'start_time'=>$_POST['start_time'],'end_time'=>$_POST['end_time'],'capacity'=>(int)$_POST['capacity'],'price'=>(float)$_POST['price']]);} $classes=FitnessClass::allUpcoming(); ?>
<!doctype html><html><head><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-[#F5E9DA] p-6"><div class="max-w-6xl mx-auto"><form method="POST" class="bg-white p-4 rounded shadow grid grid-cols-1 md:grid-cols-2 gap-3"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(Csrf::token())?>"><input required name="title" placeholder="Title" class="border p-2 rounded"><input name="instructor_id" placeholder="Instructor ID" class="border p-2 rounded"><input type="datetime-local" name="start_time" required class="border p-2 rounded"><input type="datetime-local" name="end_time" required class="border p-2 rounded"><input type="number" name="capacity" required class="border p-2 rounded"><input type="number" step="0.01" name="price" required class="border p-2 rounded"><textarea name="description" class="border p-2 rounded md:col-span-2"></textarea><button class="bg-[#C9A227] text-white p-2 rounded">Create Class</button></form><div class="mt-4 bg-white p-4 rounded shadow"><?php foreach($classes as $c): ?><div class="border-b py-2"><?=htmlspecialchars($c['title'])?> - <?=htmlspecialchars($c['start_time'])?></div><?php endforeach; ?></div></div></body></html>
